from pathlib import Path
r=Path('apps/storefront')
(r/'components/checkout.tsx').write_text('''"use client";
import {useEffect,useRef,useState} from 'react';import Link from 'next/link';import {useRouter} from 'next/navigation';import {ArrowRight,Minus,Plus,Trash2,ShoppingBag,LockKeyhole,Truck} from 'lucide-react';import {money,price,Product,storeRequest} from '@/lib/store';import {useStore,ProductImage} from './store';
export function Cart(){const {cart,data,setQuantity}=useStore();const lines=cart.map((line:any)=>({...line,product:data.products.find((p:Product)=>p.id===line.id)})).filter((line:any)=>line.product);const subtotal=lines.reduce((total:number,line:any)=>total+price(line.product)*line.quantity,0);return <main id="main" className="container commerce-page"><div className="breadcrumbs"><Link href="/">Home</Link><span>/</span>Your bag</div><span className="eyebrow">A FEW GOOD CHOICES</span><h1>Your shopping bag.</h1>{lines.length?<div className="cart-layout"><section>{lines.map((line:any)=><article className="cart-line" key={line.id}><Link href={'/products/'+line.product.slug}><ProductImage product={line.product}/></Link><div><small>{line.product.sku}</small><Link href={'/products/'+line.product.slug}><h3>{line.product.name}</h3></Link><strong>{money(price(line.product))}</strong><div className="cart-line-controls"><div className="quantity"><button aria-label={'Decrease '+line.product.name} onClick={()=>setQuantity(line.id,line.quantity-1)}><Minus size={14}/></button><span>{line.quantity}</span><button aria-label={'Increase '+line.product.name} disabled={line.quantity>=line.product.stock-(line.product.reserved||0)} onClick={()=>setQuantity(line.id,line.quantity+1)}><Plus size={14}/></button></div><button className="remove-link" onClick={()=>setQuantity(line.id,0)}><Trash2 size={14}/>Remove</button></div></div><strong className="cart-line-total">{money(price(line.product)*line.quantity)}</strong></article>)}<Link className="text-link" href="/products">Continue exploring <ArrowRight size={16}/></Link></section><aside className="order-summary"><h2>A little closer to home.</h2><div><span>Subtotal</span><strong>{money(subtotal)}</strong></div><p>Delivery, applicable VAT and discounts are calculated when you review your order.</p><Link className="button" href="/checkout">Continue to checkout <ArrowRight size={16}/></Link><span className="checkout-assurance"><LockKeyhole size={15}/>Your details are kept private</span></aside></div>:<div className="empty-state"><ShoppingBag size={48}/><h2>Your bag is waiting for a good find.</h2><p>Discover something useful for your everyday.</p><Link className="button" href="/products">Explore products</Link></div>}</main>}
export function Checkout(){const {cart,data,account,setCart}=useStore();const router=useRouter();const [form,setForm]=useState<any>({name:'',email:'',phone:'',address:'',county_code:'',delivery_zone_id:'',payment_method_id:'',coupon_code:''}),[quote,setQuote]=useState<any>(null),[busy,setBusy]=useState(false),[error,setError]=useState('');const key=useRef('');useEffect(()=>{if(account)setForm((old:any)=>({...old,name:account.name,email:account.email,phone:account.phone||''}));},[account?.id]);const counties=Object.entries(data.locations.countries.KE.counties).sort((a,b)=>String(a[1]).localeCompare(String(b[1])));const zones=data.delivery_zones.filter((zone:any)=>zone.county_codes?.includes(form.county_code));const methods=data.payment_methods.filter((method:any)=>method.category==='Manual');const update=(name:string,value:string)=>{setForm((old:any)=>({...old,[name]:value,...(name==='county_code'?{delivery_zone_id:''}:{})}));setQuote(null);key.current='';setError('');};const payload=()=>({...form,lines:cart.map((line:any)=>({product_id:line.id,quantity:line.quantity}))});const submit=async(event:React.FormEvent)=>{event.preventDefault();if(busy)return;setBusy(true);setError('');try{if(!quote){const totals=await storeRequest('quote','POST',payload());setQuote(totals);}else{key.current||=crypto.randomUUID();const result=await storeRequest('checkout','POST',payload(),key.current);setCart([]);router.push('/orders/'+result.order.id);router.refresh();}}catch(error:any){setError(error.message);}finally{setBusy(false);}};
 return <main id="main" className="container commerce-page"><div className="breadcrumbs"><Link href="/cart">Your bag</Link><span>/</span>Checkout</div><span className="eyebrow">LET US TAKE IT FROM HERE</span><h1>Good things, on their way.</h1>{cart.length?<form className="checkout-layout" onSubmit={submit}><div className="checkout-fields">{!account&&<div className="sign-in-note">Already have an account? <Link href="/account">Sign in</Link>, or continue below as a guest.</div>}{error&&<div className="form-feedback error" role="alert">{error}</div>}<section><h2><span>01</span>Your details</h2><div className="form-grid">{[['name','Full name','text'],['email','Email address','email'],['phone','Phone number','tel']].map(([name,label,type])=><label key={name}>{label}<input type={type} value={form[name]} required maxLength={name==='phone'?50:180} onChange={event=>update(name,event.target.value)}/></label>)}</div></section><section><h2><span>02</span>Where should we deliver?</h2>{account?.addresses?.length>0&&<div className="saved-addresses">{account.addresses.map((address:any,index:number)=><button type="button" key={index} className="button secondary" onClick={()=>{setForm((old:any)=>({...old,address:address.address,county_code:address.county_code,delivery_zone_id:''}));setQuote(null);}}>{address.address}</button>)}</div>}<div className="form-grid"><label>Country<input value="Kenya" readOnly/></label><label>County<select required value={form.county_code} onChange={event=>update('county_code',event.target.value)}><option value="">Select your county</option>{counties.map(([code,name])=><option key={code} value={code}>{String(name)}</option>)}</select></label><label className="wide">Street address, building and delivery directions<textarea required maxLength={1000} rows={3} value={form.address} onChange={event=>update('address',event.target.value)}/></label><label className="wide">Delivery option<select required value={form.delivery_zone_id} onChange={event=>update('delivery_zone_id',event.target.value)}><option value="">Select a delivery option</option>{zones.map((zone:any)=><option key={zone.id} value={zone.id}>{zone.name} - {money(zone.charge)}</option>)}</select>{form.county_code&&!zones.length&&<small>Delivery is currently unavailable for this county. Please contact us.</small>}</label></div></section><section><h2><span>03</span>How would you like to pay?</h2>{methods.length?methods.map((method:any)=><label className={'payment-option '+(form.payment_method_id===method.id?'selected':'')} key={method.id}><input type="radio" name="payment" required checked={form.payment_method_id===method.id} onChange={()=>update('payment_method_id',method.id)}/><span><strong>{method.name}</strong><small>{method.instructions}</small></span></label>):<div className="form-feedback">Payments are currently unavailable. <Link href="/contact">Contact us</Link> for assistance.</div>}</section><section><h2>Have a discount code?</h2><label>Discount code<input value={form.coupon_code} maxLength={50} onChange={event=>update('coupon_code',event.target.value.toUpperCase())} placeholder="Enter your code"/></label></section></div><aside className="order-summary"><h2>Your thoughtful finds</h2>{cart.map((line:any)=>{const p=data.products.find((p:Product)=>p.id===line.id);return p&&<div className="checkout-line" key={line.id}><ProductImage product={p}/><span>{p.name}<small>Quantity: {line.quantity}</small></span><strong>{money(price(p)*line.quantity)}</strong></div>})}{quote?<><div><span>Subtotal</span><strong>{money(quote.subtotal)}</strong></div>{quote.discount>0&&<div><span>Discount</span><strong>-{money(quote.discount)}</strong></div>}<div><span>VAT {quote.tax_inclusive?'(included)':''}</span><strong>{money(quote.tax_total)}</strong></div><div><span>Delivery</span><strong>{money(quote.shipping_total)}</strong></div><div className="summary-total"><span>Total</span><strong>{money(quote.total)}</strong></div></>:<p>Review your order to see the final delivery charge, applicable VAT and discount.</p>}<button className="button" disabled={busy||!methods.length}>{busy?'Please wait...':quote?'Place order':'Review order'}<ArrowRight size={16}/></button><small>By placing your order, you accept our <Link href="/terms-conditions">terms</Link>.</small></aside></form>:<div className="empty-state"><h2>Your bag is empty.</h2><Link className="button" href="/products">Explore products</Link></div>}</main>}
''')
