(r/'components/account.tsx').write_text('''"use client";
import {useEffect,useState} from 'react';import Link from 'next/link';import {useSearchParams} from 'next/navigation';import {UserRound,ArrowRight,Package,Heart,MapPin,LogOut} from 'lucide-react';import {money,storeRequest} from '@/lib/store';import {useStore,ProductCard} from './store';
export default function Account(){const {data,account,reloadAccount,wishlist,notify}=useStore();const params=useSearchParams();const [mode,setMode]=useState('login'),[tab,setTab]=useState(params.get('tab')||'orders'),[orders,setOrders]=useState<any[]>([]),[busy,setBusy]=useState(false),[message,setMessage]=useState(''),[loading,setLoading]=useState(true);useEffect(()=>{reloadAccount().then((result:any)=>{if(result)setOrders(result.orders);setLoading(false);});},[]);const favoriteProducts=data.products.filter((p:any)=>wishlist.includes(p.id));
 if(loading)return <main className="container centered" id="main"><p>Loading your account...</p></main>;
 if(!account&&tab==='wishlist')return <main id="main" className="container section"><h1>Your saved favorites.</h1><p className="muted">A few good choices for another day. <Link href="/account">Sign in</Link> to save them to your account.</p><div className="product-grid">{favoriteProducts.map((p:any)=><ProductCard key={p.id} product={p}/>)}</div>{!favoriteProducts.length&&<div className="empty-state"><h2>No favorites yet.</h2><Link className="button" href="/products">Explore products</Link></div>}</main>;
 if(!account)return <main id="main" className="container auth-page"><div className="auth-story"><span className="eyebrow">GOOD TO HAVE YOU HERE</span><h1>A little more<br/>at home.</h1><p>Keep your favorites close, follow your orders and make your next visit a little easier.</p><div><Package size={23}/>Your orders, in one place</div><div><Heart size={23}/>A collection of your favorites</div><div><MapPin size={23}/>Addresses, ready for next time</div></div><form className="auth-form" onSubmit={async event=>{event.preventDefault();if(busy)return;setBusy(true);setMessage('');const input=Object.fromEntries(new FormData(event.currentTarget));try{await storeRequest(mode,'POST',input);const result=await reloadAccount();setOrders(result?.orders??[]);notify(mode==='login'?'Welcome back.':'Your account is ready.');}catch(error:any){setMessage(error.message);}finally{setBusy(false);}}}><UserRound size={28}/><h2>{mode==='login'?'Welcome back.':'Make yourself at home.'}</h2><p>{mode==='login'?'Sign in to your Olive account.':'Create an account for a better shopping experience.'}</p>{mode==='register'&&<label>Full name<input name="name" required maxLength={180} autoComplete="name"/></label>}<label>Email address<input name="email" type="email" required maxLength={180} autoComplete="email"/></label><label>Password<input name="password" type="password" required minLength={mode==='register'?12:1} maxLength={72} autoComplete={mode==='login'?'current-password':'new-password'}/>{mode==='register'&&<small>Use at least 12 characters.</small>}</label>{message&&<p className="form-feedback error" role="alert">{message}</p>}<button className="button" disabled={busy}>{busy?'Please wait...':mode==='login'?'Sign in':'Create account'}<ArrowRight size={16}/></button><p>{mode==='login'?'New here?':'Already have an account?'} <button className="text-link" type="button" onClick={()=>{setMode(mode==='login'?'register':'login');setMessage('');}}>{mode==='login'?'Create an account':'Sign in'}</button></p><Link href="/contact" className="muted">Need help accessing your account?</Link></form></main>;
 return <main id="main" className="container account-page"><span className="eyebrow">YOUR OLIVE ACCOUNT</span><h1>Hello, {account.name.split(' ')[0]}.</h1><p className="muted">Your orders, favorites and details. All right here.</p><div className="account-tabs">{['orders','wishlist','profile','addresses'].map(value=><button key={value} className={tab===value?'selected':''} onClick={()=>{setTab(value);setMessage('');}}>{value[0].toUpperCase()+value.slice(1)}</button>)}<button onClick={async()=>{await storeRequest('logout','POST');await reloadAccount();}}><LogOut size={16}/>Sign out</button></div>{tab==='orders'&&<section>{orders.length?orders.map(order=><Link className="account-order" href={'/orders/'+order.id} key={order.id}><div><strong>{order.reference}</strong><small>{new Date(order.created_at).toLocaleDateString('en-KE')}</small></div><span className="status-pill">{order.status}</span><span>{order.payment_status}</span><strong>{money(order.total)}</strong><ArrowRight size={17}/></Link>):<div className="empty-state"><Package size={40}/><h2>Your next good find is waiting.</h2><Link className="button" href="/products">Explore products</Link></div>}</section>}{tab==='wishlist'&&<div className="product-grid">{favoriteProducts.map((p:any)=><ProductCard key={p.id} product={p}/>)}</div>}{tab==='profile'&&<form className="profile-form" onSubmit={async event=>{event.preventDefault();if(busy)return;setBusy(true);setMessage('');try{await storeRequest('profile','PATCH',Object.fromEntries(new FormData(event.currentTarget)));await reloadAccount();setMessage('Your profile has been updated.');}catch(error:any){setMessage(error.message);}finally{setBusy(false);}}}><h2>Your details</h2><label>Full name<input name="name" required maxLength={180} defaultValue={account.name}/></label><label>Email address<input readOnly value={account.email}/></label><label>Phone number<input name="phone" maxLength={50} defaultValue={account.phone}/></label><h3>Change your password</h3><label>Current password<input name="current_password" type="password" maxLength={72}/></label><label>New password<input name="password" type="password" minLength={12} maxLength={72}/></label><button className="button" disabled={busy}>Save details</button>{message&&<p className="form-feedback" role="status">{message}</p>}</form>}{tab==='addresses'&&<div className="address-layout">{account.addresses?.map((address:any,index:number)=><article className="address-card" key={index}><MapPin size={21}/><p>{address.address}</p><small>{data.locations.countries.KE.counties[address.county_code]}, Kenya</small><button className="text-link" onClick={async()=>{try{await storeRequest('profile','PATCH',{name:account.name,phone:account.phone,addresses:account.addresses.filter((_:any,i:number)=>i!==index)});await reloadAccount();}catch(error:any){setMessage(error.message);}}}>Remove address</button></article>)}<form className="profile-form" onSubmit={async event=>{event.preventDefault();if(busy)return;setBusy(true);setMessage('');const form=event.currentTarget;try{await storeRequest('profile','PATCH',{name:account.name,phone:account.phone,addresses:[...(account.addresses||[]),Object.fromEntries(new FormData(form))]});await reloadAccount();form.reset();setMessage('Address saved.');}catch(error:any){setMessage(error.message);}finally{setBusy(false);}}}><h2>Add an address</h2><label>Country<input value="Kenya" readOnly/></label><label>County<select name="county_code" required><option value="">Select county</option>{Object.entries(data.locations.countries.KE.counties).sort((a,b)=>String(a[1]).localeCompare(String(b[1]))).map(([code,name])=><option value={code} key={code}>{String(name)}</option>)}</select></label><label>Delivery address<textarea name="address" required maxLength={1000}/></label><button className="button" disabled={busy}>Save address</button>{message&&<p className="form-feedback" role="status">{message}</p>}</form></div>}</main>}
''')
