(r/'components/order.tsx').write_text('''"use client";
import {useEffect,useRef,useState} from 'react';import Link from 'next/link';import {Check,Package,Truck,ArrowRight} from 'lucide-react';import {money,storeRequest} from '@/lib/store';import {useStore} from './store';
export default function Order({id}:{id:string}){const {account}=useStore();const [order,setOrder]=useState<any>(null),[error,setError]=useState(''),[message,setMessage]=useState(''),[busy,setBusy]=useState(false);const key=useRef('');const load=()=>storeRequest('orders/'+id).then(result=>{setOrder(result.order);setError('');}).catch(error=>setError(error.message));useEffect(()=>{void load();const timer=setInterval(load,5000);return()=>clearInterval(timer);},[id]);return <main id="main" className="container order-page">{error?<div className="form-feedback error" role="alert">{error}<br/><Link href="/account">Sign in to view your orders</Link></div>:!order?<p>Loading your order...</p>:<><span className="confirmation-icon"><Check size={28}/></span><span className="eyebrow">THANK YOU FOR CHOOSING OLIVE</span><h1>Your order is with us.</h1><p>We will keep you updated here as your order moves along.</p><div className="order-reference"><strong>{order.reference}</strong><span>{new Date(order.created_at).toLocaleDateString('en-KE')}</span></div><div className="order-progress">{['Pending','Confirmed','Dispatched','Delivered'].map((stage,index)=><div key={stage} className={['Pending','Confirmed','Dispatched','Delivered'].indexOf(order.status)>=index?'complete':''}><span>{index+1}</span><strong>{stage}</strong></div>)}</div><div className="order-statuses"><span>Order: <strong>{order.status}</strong></span><span>Payment: <strong>{order.payment_status}</strong></span><span>Delivery: <strong>{order.fulfilment_status}</strong></span></div><div className="order-receipt"><section><h2>Your order</h2>{order.lines.map((line:any)=><div key={line.product_id}><span>{line.name}<small>Quantity: {line.quantity}</small></span><strong>{money(line.total)}</strong></div>)}<div><span>Subtotal</span><strong>{money(order.subtotal)}</strong></div><div><span>Discount</span><strong>-{money(order.discount)}</strong></div><div><span>VAT {order.tax_inclusive?'(included)':''}</span><strong>{money(order.tax_total)}</strong></div><div><span>Delivery</span><strong>{money(order.shipping_total)}</strong></div><div className="summary-total"><span>Total</span><strong>{money(order.total)}</strong></div></section><section><Truck size={25}/><h2>On its way to</h2><p>{order.customer_name}</p><p>{order.delivery_address}</p>{order.tracking_reference&&<p>Tracking reference: {order.tracking_reference}</p>}<h3>Status updates</h3>{order.status_history?.map((entry:any,index:number)=><div className="order-history" key={index}><strong>{entry.to}</strong><small>{new Date(entry.at).toLocaleString('en-KE')}</small></div>)}</section></div>{account&&['Pending','Confirmed'].includes(order.status)&&!['Paid','Refunded','Partially refunded'].includes(order.payment_status)&&<button className="button secondary" disabled={busy} onClick={async()=>{const reason=prompt('Please tell us why you would like to cancel this order.');if(!reason?.trim())return;setBusy(true);try{await storeRequest('orders/'+id+'/cancel','POST',{version:order.version,evidence:reason},crypto.randomUUID());await load();}catch(error:any){setMessage(error.message);}finally{setBusy(false);}}}>Cancel order</button>}{account&&order.status==='Delivered'&&['Paid','Partially refunded'].includes(order.payment_status)&&<form className="return-form" onSubmit={async event=>{event.preventDefault();setBusy(true);const form=event.currentTarget;key.current||=crypto.randomUUID();try{await storeRequest('returns','POST',{...Object.fromEntries(new FormData(form)),order_id:id},key.current);setMessage('Your return request has been submitted for review.');form.reset();key.current='';}catch(error:any){setMessage(error.message);}finally{setBusy(false);}}}><h2>Request a return</h2><label>Reason<textarea name="reason" required maxLength={2000}/></label><label>Requested refund (KSh)<input name="refund_amount" type="number" min="0.01" max={order.total} step="0.01" required/></label><button className="button" disabled={busy}>Submit return request</button></form>}{message&&<p className="form-feedback" role="status">{message}</p>}<Link className="text-link" href="/products">Continue exploring <ArrowRight size={16}/></Link></>}</main>}
''')
